// Base58 (Bitcoin alphabet) encode/decode, reimplemented from observed
// behavior. Byte sequences are plain Arrays of integers (0-255);
// arithmetic is done with BigInt.

export const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const ALPHABET_INDEX = new Map();
for (let i = 0; i < ALPHABET.length; i++) {
  ALPHABET_INDEX.set(ALPHABET[i], BigInt(i));
}

// bytes: Array<int> -> base58 string
export function b58encode(bytes) {
  // Count leading zero bytes; each becomes a leading '1'.
  let leadingZeros = 0;
  while (leadingZeros < bytes.length && bytes[leadingZeros] === 0) {
    leadingZeros++;
  }

  // Convert the remaining bytes to a BigInt.
  let num = 0n;
  for (let i = leadingZeros; i < bytes.length; i++) {
    num = (num << 8n) | BigInt(bytes[i]);
  }

  // Repeatedly divide by 58 to build the digits (least significant first).
  let digits = '';
  while (num > 0n) {
    const rem = Number(num % 58n);
    digits = ALPHABET[rem] + digits;
    num = num / 58n;
  }

  return '1'.repeat(leadingZeros) + digits;
}

// str: base58 string -> Array<int>
export function b58decode(str) {
  // Count leading '1' characters; each becomes a leading zero byte.
  let leadingOnes = 0;
  while (leadingOnes < str.length && str[leadingOnes] === '1') {
    leadingOnes++;
  }

  // Accumulate the value as a BigInt.
  let num = 0n;
  for (let i = leadingOnes; i < str.length; i++) {
    const ch = str[i];
    if (!ALPHABET_INDEX.has(ch)) {
      throw new Error(`Invalid character ${JSON.stringify(ch)}`);
    }
    num = num * 58n + ALPHABET_INDEX.get(ch);
  }

  // Convert the BigInt back to bytes (big-endian).
  const body = [];
  while (num > 0n) {
    body.unshift(Number(num & 0xffn));
    num = num >> 8n;
  }

  const result = new Array(leadingOnes).fill(0);
  for (const b of body) result.push(b);
  return result;
}

