// Reproduces CPython's repr() of a bytes object, byte-for-byte.
// bytes: Array<int> (0-255) -> string like b'...'

export function bytesRepr(bytes) {
  // Quote selection mirrors CPython: use single quotes, unless the data
  // contains a single quote and no double quote.
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) {
      out += '\\\\';
    } else if (b === quoteCode) {
      out += '\\' + quote;
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += quote;
  return out;
}

