// Minimal re-implementation of the argparse behavior used by the script:
// two required string options (--a, --b), matching Python's error style.

const PROG = 'test7.mjs';

function usage() {
  return `usage: ${PROG} [-h] --a A --b B`;
}

function fail(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  process.stdout.write(usage() + '\n\n');
  process.stdout.write('options:\n');
  process.stdout.write('  -h, --help  show this help message and exit\n');
  process.stdout.write('  --a A\n');
  process.stdout.write('  --b B\n');
  process.exit(0);
}

// Parses argv (without node/script entries) for required options --a and --b.
export function parseArgs(argv) {
  const values = { a: undefined, b: undefined };
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      printHelp();
    }

    let name = token;
    let inlineValue = undefined;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      name = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    if (name === '--a' || name === '--b') {
      const key = name.slice(2);
      if (inlineValue !== undefined) {
        values[key] = inlineValue;
      } else if (i + 1 < argv.length) {
        values[key] = argv[++i];
      } else {
        fail(`argument ${name}: expected one argument`);
      }
    } else {
      extras.push(token);
    }
  }

  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  const missing = [];
  if (values.a === undefined) missing.push('--a');
  if (values.b === undefined) missing.push('--b');
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  return values;
}

